diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 77b0c66..1389e96 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1853,6 +1853,107 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+extern "C" void c_swap_out(natw pid, char *buf)
+{
+    if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, true)) {
+        flog(LOG_WARN, "swap_out: buffer non valido");
+        c_abort_p();
+        return;
+    }
+
+    if (pid > MAX_PROC_ID || !proc_table[pid]) {
+        flog(LOG_WARN, "swap_out: pid non valido");
+        c_abort_p();
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    if (p->livello == LIV_SISTEMA) {
+        flog(LOG_WARN, "swap_out: processo di sistema");
+        c_abort_p();
+        return;
+    }
+
+    if (p == esecuzione_precedente) {
+        flog(LOG_WARN, "swap_out: processo chiamante");
+        c_abort_p();
+        return;
+    }
+
+    if (p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    vaddr stack_begin = fin_utn_p - DIM_USR_STACK;
+    unmap(p->cr3, stack_begin, fin_utn_p,
+        [&buf, &stack_begin](vaddr v, paddr pa, int) {
+            memcpy(buf + (v - stack_begin),
+                   voidptr_cast(pa), DIM_PAGINA);
+            rilascia_frame(pa);
+        });
+
+    p->swapped_out = true;
+
+    esecuzione->contesto[I_RAX] = true;
+}
+
+extern "C" void c_swap_in(natw pid, const char *buf)
+{
+    if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, false))
+        c_abort_p();
+    if (pid > MAX_PROC_ID || !proc_table[pid]) {
+        flog(LOG_WARN, "swap_in: pid non valido");
+        c_abort_p();
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    if (p->livello == LIV_SISTEMA) {
+        flog(LOG_WARN, "swap_in: processo di sistema");
+        c_abort_p();
+        return;
+    }
+
+    if (!p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    vaddr stack_begin = fin_utn_p - DIM_USR_STACK;
+    vaddr v = map(p->cr3,
+        stack_begin,
+        fin_utn_p,
+        BIT_RW | BIT_US,
+        [buf, stack_begin](vaddr va) {
+            paddr pa = alloca_frame();
+            if (pa)
+                memcpy(voidptr_cast(pa),
+                       buf + (va - stack_begin),
+                       DIM_PAGINA);
+            return pa;
+        });
+
+    if (v != fin_utn_p) {
+        unmap(p->cr3, stack_begin, v,
+            [](vaddr, paddr pa, int) { rilascia_frame(pa); });
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    p->swapped_out = false;
+
+    esecuzione->contesto[I_RAX] = true;
+
+    if (p->scheduled) {
+        p->scheduled = false;
+        inspronti();
+        inserimento_lista(pronti, p);
+        schedulatore();
+    }
+}
 //   SOLUZIONE 2025-06-05 )


